// The site's Cloudflare entry point: OpenNext's generated worker, plus a
// short edge cache for visitors who aren't signed in.
//
// Signed-out visitors all see the same pages, so each page is kept at
// Cloudflare's edge for EDGE_TTL seconds: repeat visits then cost no server
// time and no database queries. Anyone with a Supabase sign-in cookie, and
// anything that changes data or is personal, always goes to the app.
// A response header x-ltd-cache says HIT or MISS.

// Generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

const EDGE_TTL = 60;

// Pages that are personal, change data, or are Next.js/Cloudflare internals
const NEVER_CACHE = [
  "/_next", "/cdn-cgi", "/api", "/auth", "/add", "/edit", "/moderate", "/settings",
  "/notifications", "/calendar", "/following", "/submissions", "/updates/new",
];

// Headers Next.js uses for in-app navigation; the response depends on them
const VARY_HEADERS = ["rsc", "next-router-state-tree", "next-router-prefetch", "next-router-segment-prefetch", "next-url"];

function cacheable(request) {
  if (request.method !== "GET") return false;
  const { pathname } = new URL(request.url);
  if (NEVER_CACHE.some((p) => pathname === p || pathname.startsWith(`${p}/`))) return false;
  const cookie = request.headers.get("cookie") ?? "";
  return !/(^|;\s*)sb-[^=;]*-auth-token/.test(cookie);
}

function cacheKey(request) {
  const url = new URL(request.url);
  for (const h of VARY_HEADERS) {
    const value = request.headers.get(h);
    if (value) url.searchParams.set(`__ltd_${h}`, value);
  }
  return new Request(url.toString(), { method: "GET" });
}

function withHeader(response, name, value) {
  const copy = new Response(response.body, response);
  copy.headers.set(name, value);
  return copy;
}

const worker = {
  async fetch(request, env, ctx) {
    if (!cacheable(request)) return handler.fetch(request, env, ctx);

    const cache = caches.default;
    const key = cacheKey(request);
    const hit = await cache.match(key);
    if (hit) {
      // Browsers get the page's own caching rules back, not the edge's
      const out = new Response(hit.body, hit);
      out.headers.set("Cache-Control", hit.headers.get("x-ltd-browser-cache-control") ?? "private, no-cache, no-store, max-age=0, must-revalidate");
      out.headers.delete("x-ltd-browser-cache-control");
      out.headers.set("x-ltd-cache", "HIT");
      return out;
    }

    const response = await handler.fetch(request, env, ctx);
    if (response.status !== 200 || response.headers.has("set-cookie")) return withHeader(response, "x-ltd-cache", "BYPASS");

    const [forVisitor, forCache] = response.body ? response.body.tee() : [null, null];
    const stored = new Response(forCache, response);
    stored.headers.set("x-ltd-browser-cache-control", response.headers.get("Cache-Control") ?? "");
    stored.headers.set("Cache-Control", `public, max-age=${EDGE_TTL}`);
    stored.headers.delete("vary");
    ctx.waitUntil(cache.put(key, stored));

    const out = new Response(forVisitor, response);
    out.headers.set("x-ltd-cache", "MISS");
    return out;
  },
};

export default worker;
